"""Independent event-time budget algebra, no model or World imports."""
import json,sys
from pathlib import Path

def verify(case):
    cold,post=case['cold'],case['post'];energy=12;warm=16;fresh=set(range(16,32));heat=55;constructor=73;last=0;successes=0;opps=set();caps=0
    expected_actions={2:0,4:1,**{12+8*k:k%2 for k in range(63)}}
    for r in case['trace']:
        t=r['tick'];assert t==last+1;last=t
        assert r['before']==energy
        expired=[]
        if t==64:
            expired=list(range(16-warm,16));heat+=20*warm;warm=0;constructor-=16;heat+=16
        for p in sorted(fresh):
            if t>=64+13*(p-15):expired.append(p);fresh.remove(p);heat+=20
        assert r['expired']==expired
        energy-=1;heat+=1;packet=None;success=None;gain=0;loss=0
        assert r['port']==expected_actions.get(t)
        if t in expected_actions:
            port=expected_actions[t]
            if t<64 and warm:
                packet=16-warm;success=int(port==cold)
                if success:warm-=1
            elif t>=64:
                p=16+(t-64)//13
                if p in fresh and p<32:packet=p;fresh.remove(p);success=int(port==post);opps.add(p)
            if packet is not None:
                if success:
                    gain=min(20,64-energy);loss=20-gain;energy+=gain;heat+=loss;caps+=loss;successes+=int(packet>=16)
                elif packet>=16:heat+=20
        assert (r['packet'],r['success'],r['gain'],r['cap_loss'],r['energy'],r['heat'],r['constructor'],r['remaining_food'])==(packet,success,gain,loss,energy,heat,constructor,32+warm+len(fresh))
        assert energy+heat+constructor+20*(32+warm+len(fresh))==1420
        if energy==0:assert t==case['ticks']
    assert case['ticks']==last and case['post_food']==successes and case['fresh_attempts']==len(opps) and case['cap_loss']==caps
    assert energy==0 or last==512
    return dict(cold=cold,post=post,ticks=last,post_food=successes,fresh_attempts=len(opps),cap_loss=caps,heat=heat,constructor=constructor,remaining_food=32+warm+len(fresh),energy=energy)

if __name__=='__main__':
    data=json.loads(Path(sys.argv[1]).read_bytes());assert data['software_only'] and data['new_world_histories']==0 and data['seeds_executed']==[]
    assert [(x['cold'],x['post']) for x in data['counterfactuals']]==[(0,0),(0,1),(1,0),(1,1)]
    from experiments.digital_contingency15_endpoint import endpoint
    rows=[]
    for case in data['counterfactuals']:
        row=verify(case);row['analytical_endpoint']=endpoint(dict(verified=True,**row),4);rows.append(row)
    print(json.dumps(dict(verified=True,classification='REJECT AUTOMATIC RELEASE07 TO TASK15 TRANSFER',new_world_histories=0,paid_viability=None,learning=False,stage_credit=False,scope='Four analytical no-noise cold/post orientations; not seed realizations or exhaustive noisy law',rows=rows),sort_keys=True))
